import pocketbase from "../../../services/pocketbase";
import { Contato, Texto } from "../../../services/types";
import styles from "./Card.module.css";
import React, { useEffect, useState } from "react";
import parse from "html-react-parser";

const Card = () => {
  const [data, setData] = useState<Texto>();
  const [links, setLinks] = useState<Contato[]>([]);

  useEffect(() => {
    (async () => {
      setData(
        await pocketbase
          .collection("textos")
          .getFirstListItem("identificador='convite'"),
      );
      setLinks(
        await pocketbase
          .collection("contatos")
          .getFullList({ filter: "convite=True" }),
      );
    })();
  }, []);

  return (
    <div className={styles.container}>
      <div className={styles.text}>
        <h1>{data?.titulo}</h1>
        <div>{data ? parse(data.texto) : null}</div>
        <div className={styles.icons}>
          {links.map((link: Contato) => {
            if (link.icone === "pi-lichess") {
              return (
                <i
                  key={link.id}
                  onClick={() => window.open(link.url, "_blank")}
                  style={{ cursor: "pointer" }}
                  className={"defaultHover pi " + link.icone}
                >
                  <svg
                    version="1.0"
                    xmlns="http://www.w3.org/2000/svg"
                    viewBox="0 0 500 500"
                    preserveAspectRatio="xMidYMid meet"
                  >
                    <g
                      transform="translate(0,500) scale(0.1,-0.1)"
                      fill="currentColor"
                      stroke="currentColor"
                    >
                      <path d="M3615 4623 c-289 -35 -530 -110 -677 -211 l-43 -29 -270 0 c-362 -1 -572 -28 -847 -108 -325 -96 -588 -244 -810 -454 -338 -321 -540 -748 -589 -1248 -14 -140 -6 -401 16 -520 25 -140 76 -319 115 -408 123 -278 214 -416 395 -604 172 -178 335 -301 539 -406 253 -130 440 -190 766 -246 117 -21 501 -17 624 5 386 69 674 208 906 436 103 101 190 214 190 246 0 13 -9 28 -20 34 -18 10 -29 4 -79 -43 -153 -141 -281 -233 -445 -317 -213 -110 -462 -180 -692 -195 -55 -4 -112 -8 -128 -10 -43 -5 -258 13 -361 30 -622 108 -1148 506 -1416 1070 -53 112 -101 243 -119 325 -42 190 -44 208 -44 405 0 206 7 266 52 430 29 103 50 157 114 285 181 366 454 649 787 816 309 154 690 215 1061 168 242 -30 208 -33 307 27 186 112 402 209 467 209 24 0 22 -5 -49 -208 l-57 -163 85 -142 c47 -78 167 -279 267 -445 100 -167 189 -318 199 -335 16 -28 96 -162 463 -776 l81 -135 -16 -72 c-35 -160 -124 -278 -261 -344 -109 -53 -125 -52 -155 8 -42 84 -133 194 -286 348 -155 155 -218 205 -560 435 -179 120 -374 263 -485 356 -85 72 -232 222 -277 284 -90 122 -134 252 -115 337 8 35 7 46 -7 63 -25 31 -55 18 -69 -30 -19 -61 -15 -207 8 -288 32 -114 122 -273 224 -393 56 -66 281 -285 366 -357 47 -39 164 -132 260 -207 96 -75 213 -167 260 -205 94 -77 315 -298 404 -404 75 -90 166 -213 166 -226 0 -21 41 -39 73 -31 96 23 271 102 373 168 81 53 195 161 237 225 65 101 82 159 82 287 l0 115 -51 90 c-28 50 -65 116 -83 148 -84 155 -89 163 -221 402 -9 17 -59 107 -110 200 -51 94 -102 186 -113 205 -11 19 -33 60 -50 90 -16 30 -62 114 -102 185 -40 72 -114 207 -165 300 -51 94 -102 185 -112 204 -15 26 -17 40 -9 65 5 17 19 74 31 126 12 52 34 149 50 215 56 235 57 234 -75 218z" />
                    </g>
                  </svg>
                </i>
              );
            } else {
              return (
                <i
                  key={link.id}
                  onClick={() => window.open(link.url, "_blank")}
                  style={{ cursor: "pointer" }}
                  className={"defaultHover pi " + link.icone}
                />
              );
            }
          })}
        </div>
      </div>
    </div>
  );
};

export default Card;
